BOOL WINAPI SetupDestroyDiskSpaceList(HDSKSPC handle)
{
    struct disk_space_list *list = handle;

    for (size_t i = 0; i < list->count; ++i)
        free(list->files[i].path);
    free(list->files);
    free(list);
    return TRUE;
}

